import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cpp_src = "torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);"
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <cstdint>
constexpr int kThreads = 256;
constexpr int kRowsPerBlock = 8;
constexpr int kTileFloats = 1024;
constexpr int kTileVecs = kTileFloats / 4;
constexpr int kSplitK = 16;
__global__ void matvec_tiled_vec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    long M,
    long K)
{
    __shared__ float4 sB[kTileVecs];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const long row = (long)blockIdx.x * kRowsPerBlock + warp;
    const bool active = row < M;
    const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);
    float acc = 0.0f;
    const long num_tiles = K >> 10;
    for (long t = 0; t < num_tiles; ++t) {
        const long base_vec = t << 8;
        for (int i = threadIdx.x; i < kTileVecs; i += blockDim.x) {
            sB[i] = B4[base_vec + i];
        }
        __syncthreads();
        if (active) {
            const float4* __restrict__ A4 = reinterpret_cast<const float4*>(A + row * K);
            #pragma unroll 4
            for (int v = lane; v < kTileVecs; v += 32) {
                const float4 a = A4[base_vec + v];
                const float4 b = sB[v];
                acc += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
            }
        }
        __syncthreads();
    }
    const unsigned int mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(mask, acc, offset);
    }
    if (active && lane == 0) {
        C[row] = acc;
    }
}
// Split-K GEMV: K is very large while M is modest, so partition the K
// reduction across blockIdx.y to expose far more memory-level parallelism
// (many more CTAs streaming disjoint slabs of A) and finish with atomicAdd.
__global__ void matvec_splitk_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    long M,
    long K,
    long k_chunk)
{
    const long row = blockIdx.x;
    const int split = blockIdx.y;
    const long k_begin = (long)split * k_chunk;
    const float* __restrict__ Arow = A + row * K + k_begin;
    const float* __restrict__ Bseg = B + k_begin;
    const float4* __restrict__ A4 = reinterpret_cast<const float4*>(Arow);
    const float4* __restrict__ B4 = reinterpret_cast<const float4*>(Bseg);
    const long G = k_chunk >> 2;
    float acc = 0.0f;
    #pragma unroll 4
    for (long g = threadIdx.x; g < G; g += blockDim.x) {
        const float4 a = A4[g];
        const float4 b = B4[g];
        acc += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }
    __shared__ float warp_sums[32];
    const unsigned int mask = 0xffffffffu;
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(mask, acc, offset);
    }
    if (lane == 0) {
        warp_sums[warp] = acc;
    }
    __syncthreads();
    if (warp == 0) {
        const int num_warps = (blockDim.x + 31) >> 5;
        float sum = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
        }
        if (lane == 0) {
            atomicAdd(&C[row], sum);
        }
    }
}
__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    long K,
    bool use_vec)
{
    const long row = blockIdx.x;
    const float* __restrict__ Arow = A + row * K;
    float acc = 0.0f;
    if (use_vec) {
        const long G = K >> 2;
        const float4* __restrict__ A4 = reinterpret_cast<const float4*>(Arow);
        const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);
        #pragma unroll 4
        for (long g = threadIdx.x; g < G; g += blockDim.x) {
            const float4 a = A4[g];
            const float4 b = B4[g];
            acc += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        }
    } else {
        for (long k = threadIdx.x; k < K; k += blockDim.x) {
            acc += Arow[k] * B[k];
        }
    }
    __shared__ float warp_sums[32];
    const unsigned int mask = 0xffffffffu;
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(mask, acc, offset);
    }
    if (lane == 0) {
        warp_sums[warp] = acc;
    }
    __syncthreads();
    if (warp == 0) {
        const int num_warps = (blockDim.x + 31) >> 5;
        float sum = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
        }
        if (lane == 0) {
            C[row] = sum;
        }
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 && B.scalar_type() == torch::kFloat32,
                "A and B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "A must have shape (M, K)");
    auto Ac = A.contiguous();
    auto Bc = B.contiguous();
    const int64_t M = Ac.size(0);
    const int64_t K = Ac.size(1);
    auto C = torch::zeros({M, 1}, Ac.options());
    if (M == 0) {
        return C;
    }
    c10::cuda::CUDAGuard device_guard(Ac.device());
    const float* Aptr = Ac.data_ptr<float>();
    const float* Bptr = Bc.data_ptr<float>();
    float* Cptr = C.data_ptr<float>();
    const bool aligned16 =
        ((reinterpret_cast<std::uintptr_t>(Aptr) & 15) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(Bptr) & 15) == 0);
    const bool use_vec = ((K & 3) == 0) && aligned16;
    const bool use_splitk = use_vec && ((K % (kSplitK * 4)) == 0) && (K >= (kSplitK * kThreads * 4));
    cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();
    if (use_splitk) {
        const long k_chunk = K / kSplitK;  // multiple of 4, 16B-aligned segments
        const dim3 block(kThreads);
        const dim3 grid(static_cast<unsigned int>(M), static_cast<unsigned int>(kSplitK));
        matvec_splitk_kernel<<<grid, block, 0, stream>>>(Aptr, Bptr, Cptr, M, K, k_chunk);
    } else {
        const dim3 block(kThreads);
        const dim3 grid(static_cast<unsigned int>(M));
        matvec_kernel<<<grid, block, 0, stream>>>(Aptr, Bptr, Cptr, K, use_vec);
    }
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
    return C;
}
"""
_matvec_ext = load_inline(
    name="matvec_fused_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matvec_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matvec_ext.matvec_cuda(A, B)

